 $badAcl.aclEstablishment[0].reason='DESCRIPTOR_MISMATCH';$badAcl.aclCorroboration[0].descriptor=$badAcl.aclEstablishment[0].actual
 $vbad=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $vbad $badAcl 'SIMULATED_PASS' $journal.ToArray();if($vbad.cases.aclEstablishment.state -cne 'FAIL'){throw "verified ACL mismatch lost: $case"}
}
