$relabeled=$ev.Clone();$relabeled.aclEstablishment=@($records.ToArray()|ForEach-Object {$x=$_.Clone();$x.source='LIVE';$x});$relabeled.aclCorroboration=@($observations.ToArray()|ForEach-Object {$x=$_.Clone();$x.source='LIVE';$x});$relabeled.aclFixtureBinding=$ev.aclFixtureBinding.Clone();$relabeled.aclFixtureBinding.source='LIVE';$rv=New-PhaseAManagerVerdictInput ('1'*40) '123';Add-PhaseAStage3Evidence $rv $relabeled 'LIVE_OBSERVED' $journal.ToArray();if($rv.cases.aclEstablishment.state -cne 'NOT_RUN'){throw 'relabeled injected temporary fixture accepted as live'}
