$journal3=New-Object 'System.Collections.Generic.List[object]';$wrapped3=New-PhaseAActorJournalBackend $failingActors $journal3;$sink3=@{};$result3=Invoke-PhaseAStages $true $true $accountBackend $wrapped3 $true $failingFixture $sink3
